// ==========================================================================
// Music2::MusicUpdate(void)
// @001EA270  136 bytes
// ==========================================================================
void Music2::MusicUpdate()
{
    if (mFadeOutCounter <= 0)
    {
        // Not fading: keep the playing song in step with the pause volume.
        float aVolume = mPauseVolume;
        if (aVolume != mNormalVolume)
        {
            mNormalVolume = aVolume;
            mMusicInterface->SetSongVolume(mCurMusicFileMain, aVolume);
        }
    }
    else
    {
        int aRemaining = mFadeOutCounter - 1;
        mFadeOutCounter = aRemaining;
        if (aRemaining != 0)
        {
            float aScale = AnimateFadeOutVolume(mFadeOutDuration, aRemaining);
            mMusicInterface->SetSongVolume(mCurMusicFileMain, aScale * mPauseVolume);
        }
        else
        {
            // The fade has run its course.
            StopAllMusic();
        }
    }

    UpdateMusicBurst();
}

