// ==========================================================================
// Music2::StartGameMusic(bool)
// @001EA330  316 bytes
// ==========================================================================
void Music2::StartGameMusic(bool theStart)
{
    if (theStart)
        StopAllMusic();

    LawnApp *anApp = mApp;

    // The tune is chosen from the game mode first, then from what the level
    // itself is, and the day theme is the fallback.
    GameMode aGameMode = anApp->mGameMode;
    if (aGameMode == GAMEMODE_CHALLENGE_ZEN_GARDEN || aGameMode == GAMEMODE_TREE_OF_WISDOM)
        MakeSureMusicIsPlaying(MUSIC_TUNE_ZEN_GARDEN); // MUSIC_TUNE_ZEN_GARDEN
    else if (anApp->IsFinalBossLevel())
        MakeSureMusicIsPlaying(MUSIC_TUNE_FINAL_BOSS_BRAINIAC_MANIAC); // MUSIC_TUNE_FINAL_BOSS_BRAINIAC_MANIAC
    else if (anApp->IsWallnutBowlingLevel())
        MakeSureMusicIsPlaying(MUSIC_TUNE_MINIGAME_LOONBOON); // MUSIC_TUNE_MINIGAME_LOONBOON
    else if (anApp->IsWhackAZombieLevel())
        MakeSureMusicIsPlaying(MUSIC_TUNE_MINIGAME_LOONBOON);
    else if (anApp->IsLittleTroubleLevel())
        MakeSureMusicIsPlaying(MUSIC_TUNE_MINIGAME_LOONBOON);
    else if (anApp->IsBungeeBlitzLevel())
        MakeSureMusicIsPlaying(MUSIC_TUNE_MINIGAME_LOONBOON);
    else if (anApp->mGameMode == GAMEMODE_CHALLENGE_SPEED)
        MakeSureMusicIsPlaying(MUSIC_TUNE_MINIGAME_LOONBOON);
    else if (anApp->IsAdventureMode() &&
        (anApp->mPlayerInfo->mLevel == 20 || anApp->mPlayerInfo->mLevel == 10 || anApp->mPlayerInfo->mLevel == 30))
        MakeSureMusicIsPlaying(MUSIC_TUNE_CONVEYER); // MUSIC_TUNE_CONVEYER
    else if (anApp->mGameMode == GAMEMODE_CHALLENGE_COLUMN)
        MakeSureMusicIsPlaying(MUSIC_TUNE_CONVEYER);
    else if (anApp->IsStormyNightLevel())
        StopAllMusic();
    else if (anApp->IsScaryPotterLevel() || anApp->IsIZombieLevel())
        MakeSureMusicIsPlaying(MUSIC_TUNE_PUZZLE_CEREBRAWL); // MUSIC_TUNE_PUZZLE_CEREBRAWL
    else
    {
        Board *aBoard = anApp->mBoard;
        if (aBoard->mBackground == (int)BACKGROUND_4_FOG)
            MakeSureMusicIsPlaying(MUSIC_TUNE_FOG_RIGORMORMIST); // MUSIC_TUNE_FOG_RIGORMORMIST
        else if (aBoard->StageIsNight())
            MakeSureMusicIsPlaying(MUSIC_TUNE_NIGHT_MOONGRAINS); // MUSIC_TUNE_NIGHT_MOONGRAINS
        else if (aBoard->StageHasPool())
            MakeSureMusicIsPlaying(MUSIC_TUNE_POOL_WATERYGRAVES); // MUSIC_TUNE_POOL_WATERYGRAVES
        else if (aBoard->StageHasRoof())
            MakeSureMusicIsPlaying(MUSIC_TUNE_ROOF_GRAZETHEROOF); // MUSIC_TUNE_ROOF_GRAZETHEROOF
        else
            MakeSureMusicIsPlaying(MUSIC_TUNE_DAY_GRASSWALK); // MUSIC_TUNE_DAY_GRASSWALK
    }
}

